"use client";

import Image from "next/image";
import { useState, type CSSProperties } from "react";
import type { CatalogCard } from "@/lib/api/contracts";
import measuredOrbs from "./card-orbs.json";
import styles from "./cards.module.css";

type Orb = [x: number, y: number, radius: number];

/**
 * Where the two orbs are in each creature's art, in % of the card (x and radius of the width, y of the height).
 * Frames differ by rarity and Theory, so every card has its own measure: generated by
 * scripts/seed-immagini/misura-sfere.py from "docs/Carte definitive". Art not measured yet uses the average.
 */
const ORBS = measuredOrbs as unknown as Record<string, [Orb, Orb]>;
const AVERAGE_ORBS: [Orb, Orb] = [[12.26, 7.47, 4.33], [87.77, 7.52, 4.32]];

function orbStyle([x, y, radius]: Orb): CSSProperties {
  return {
    left: `${x}%`,
    top: `${y}%`,
    width: `${radius * 2}cqw`,
    height: `${radius * 2}cqw`,
    fontSize: `${radius * 1.3}cqw`,
  };
}

/** URLs that answered 404 in this tab: they are not requested again. */
const missingArt = new Set<string>();

/** ATK and DEF shown in the orbs of the art. In a battle they can differ from the card's base values. */
export type CardStats = { atk: number; def: number };

function statClass(current: number, base: number | null): string {
  if (base === null || current === base) return "";
  return current > base ? styles.statUp : styles.statDown;
}

/**
 * The card's illustration laid over the text face. It stays invisible until it has loaded and is removed when the
 * file is missing, so cards without art keep the text face underneath. For creatures, ATK and DEF are written in
 * the two orbs at the top of the frame (same place on every frame).
 */
export function CardArt({
  card,
  sizes = "200px",
  priority = false,
  stats,
}: {
  card: CatalogCard;
  sizes?: string;
  priority?: boolean;
  stats?: CardStats;
}) {
  const url = card.imageUrl;
  const [state, setState] = useState<{ url: string | null; status: "loading" | "loaded" | "missing" }>({ url, status: "loading" });
  const status = state.url === url ? state.status : "loading";

  if (!url || status === "missing" || missingArt.has(url)) return null;
  const atk = stats?.atk ?? card.atk;
  const def = stats?.def ?? card.def;
  const orbs = ORBS[String(card.id)] ?? AVERAGE_ORBS;
  return (
    <>
      <Image
        alt={card.name}
        className={`${styles.art} ${status === "loaded" ? styles.artLoaded : ""}`}
        fill
        onError={() => {
          missingArt.add(url);
          setState({ url, status: "missing" });
        }}
        onLoad={() => setState({ url, status: "loaded" })}
        priority={priority}
        sizes={sizes}
        src={url}
        unoptimized
      />
      {status === "loaded" && atk !== null && def !== null && (
        // Decorative: the text face under the art keeps ATK and DEF for screen readers
        <span className={styles.orbLayer} aria-hidden="true">
          <span className={`${styles.orb} ${statClass(atk, card.atk)}`} style={orbStyle(orbs[0])}>{atk}</span>
          <span className={`${styles.orb} ${statClass(def, card.def)}`} style={orbStyle(orbs[1])}>{def}</span>
        </span>
      )}
    </>
  );
}
